package com.peakhospital.backend.accounts;

import com.peakhospital.backend.model.Role;

/** Admin creates an account. The password is generated by the server, never typed by the admin. */
public record CreateUserRequest(
        String username,
        String fullName,
        Role role,
        String doctorId,   // required when role is DOCTOR
        String patientId   // required when role is PATIENT
) {
}
